


/** Pickup details. For a pickup that checkout creates, location_name, address, and instructions name the store the buyer chose and the delivery method's pickup instructions. The note the buyer left for the store is in recipient.instructions. */ export type PickupFulfillmentDetails = { /** Address where the buyer collects the order. */ "address"?: { "city": string; /** ISO 3166-1 alpha-2 country code. minLength: 2. maxLength: 2. pattern: ^[A-Z]{2}$. Example: "US". */ "country": string; "line1": string; "line2"?: string; "postal_code": string; "state": string; }; /** Instructions specific to curbside handoff. maxLength: 2048. */ "curbside_instructions"?: string; /** Buyer-reported arrival time for curbside or counter pickup. Format: date-time. */ "customer_arrived_at"?: string; /** Deadline after which an uncollected pickup should enter merchant review. Format: date-time. */ "expires_at"?: string; /** Pickup instructions for the buyer, such as where to go on arrival. */ "instructions"?: string; /** Name of the store or place where the buyer collects the order. */ "location_name"?: string; /** RFC3339 timestamp. Format: date-time. */ "picked_up_at"?: string; "pickup_mode"?: "in_store" | "curbside" | "locker" | "other" | (string & {}); /** Width of the promised pickup window, from 0 to 86400 seconds. Use an exact numeric string, not a floating-point number. Format: int64. minimum: 0. maximum: 86400. */ "pickup_window_duration_seconds"?: string; /** Expected preparation time for restaurant and made-to-order pickup, from 0 to 86400 seconds. Use an exact numeric string, not a floating-point number. Format: int64. minimum: 0. maximum: 86400. */ "prep_time_duration_seconds"?: string; /** RFC3339 timestamp. Format: date-time. */ "ready_at"?: string; "timezone"?: string; /** Buyer vehicle description used for curbside handoff. maxLength: 500. */ "vehicle_description"?: string; /** RFC3339 timestamp. Format: date-time. */ "window_end_at"?: string; /** RFC3339 timestamp. Format: date-time. */ "window_start_at"?: string; };
